{
	if (!Engine || !Engine->IsMatchInitialized()) return false;
	if (ItemId <= 0 || PlayerId <= 0) return false;

	const auto* Def = GetItemData(ItemId);
	if (!Def) return false;
	if (!Engine->IsItemUsableNow(PlayerId, ItemId)) return false;
	if (!ValidateTarget(Engine, ItemId, TargetCell, TargetPlayerIndex)) return false;

	// Effect-specific preconditions (no mutation yet).
	switch (Def->Type)
	{
	case EGomokuItemType::SealStone:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State != ECellState::Empty) return false;
		break;
	}
	case EGomokuItemType::Steal:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State == ECellState::Empty) return false;
		if (Engine->IsCellGuardianProtected(TargetCell.X, TargetCell.Y)) return false;
		break;
	}
	case EGomokuItemType::Pull:
	{
		const auto TC = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (TC.State != ECellState::Empty) return false;

		static const FIntPoint Dir[4] = {FIntPoint(0,-1),FIntPoint(0,1),FIntPoint(-1,0),FIntPoint(1,0)};
		FIntPoint Src = FIntPoint(INDEX_NONE);
		for (const auto& D : Dir)
		{
			const FIntPoint N = TargetCell + D;
			if (!Engine->IsValidCoordinate(N.X, N.Y)) continue;
			const auto NC = Engine->GetBoardCell(N.X, N.Y);
			if (NC.State == ECellState::Empty || NC.State == ECellState::Blocked) continue;
			if (Engine->IsCellGuardianProtected(N.X, N.Y)) continue;
			Src = N;
			break; // first valid adjacent stone wins.
		}
		if (!Src.IsValid()) return false;

		const int32 SrcOwner = Engine->CellStateToPlayerId(Engine->GetCellState(Src.X, Src.Y));
		if (SrcOwner == PlayerId) return false; // opponent-only for Pull.
		break;
	}
	case EGomokuItemType::GuardianBarrier:
	{
		const auto C = Engine->GetBoardCell(TargetCell.X, TargetCell.Y);
		if (C.State == ECellState::Empty) return false;
		break;
	}
	default: break;
	}

