	}
	case EGomokuItemType::Pull:
	{
		static const FIntPoint Dir[4] = {FIntPoint(0,-1),FIntPoint(0,1),FIntPoint(-1,0),FIntPoint(1,0)};
		FIntPoint Src = FIntPoint(INDEX_NONE);
		for (const auto& D : Dir)
		{
			const FIntPoint N = TargetCell + D;
			if (!Engine->IsValidCoordinate(N.X, N.Y)) continue;
			const auto NC = Engine->GetBoardCell(N.X, N.Y);
			if (NC.State == ECellState::Empty || NC.State == ECellState::Blocked) continue;
			if (Engine->IsCellGuardianProtected(N.X, N.Y)) continue;
			Src = N;
			break;
		}
		if (!Src.IsValid()) return false;

		const int32 SrcOwner = Engine->CellStateToPlayerId(Engine->GetCellState(Src.X, Src.Y));
		if (SrcOwner == PlayerId) return false; // opponent-only.

		if (!Engine->RemoveStoneAt(Src.X, Src.Y)) return false;
		if (!Engine->ForcePlaceStone(SrcOwner, TargetCell.X, TargetCell.Y)) return false;

		// Clear guardian on source if present (no-op if not protected).
		Engine->SetCellGuardianProtected(Src.X, Src.Y, false);

		// Recheck win at target and cache result.
		const FGomokuWinResult W = Engine->CheckWinAt(TargetCell);
		Engine->LastItemWinResult = W;
		break;
	}
	case EGomokuItemType::GuardianBarrier:
	{
		if (!Engine->SetCellGuardianProtected(TargetCell.X, TargetCell.Y, true)) return false;
		break;
	}
	default:
		return false;
	}

	// Only on success: consume energy, remove item, mark used.
	if (!Engine->ConsumePlayerEnergy(PlayerId, Def->EnergyCost)) return false;
	if (!Engine->RemoveItemFromInventory(PlayerId, ItemId)) return false;
	Engine->SetUsedItemThisTurn(PlayerId);
	return true;
}

